110	static void sf32lb52_bt_clean_nvds_shared(void)
111	{
112	  up_clean_dcache((uintptr_t)SF32LB52_BT_NVDS_BUF_START,
113	                  (uintptr_t)SF32LB52_BT_NVDS_BUF_START +
114	                  SF32LB52_BT_NVDS_BUF_SIZE);
115	}
