117	static bool sf32lb52_bt_rx_ring_valid(struct circular_buf *rx_ring)
118	{
119	  uint32_t rd_ptr = rx_ring->read_idx_mirror;
120	  uint32_t wr_ptr = rx_ring->write_idx_mirror;
121	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
122	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
123	  long buf_size = rx_ring->buffer_size;
124	
125	  return buf_size == (long)SF32LB52_BT_RING_DATA_SIZE &&
126	         rd_idx <= SF32LB52_BT_RING_DATA_SIZE &&
127	         wr_idx <= SF32LB52_BT_RING_DATA_SIZE;
128	}
129	
130	static bool sf32lb52_bt_rx_ring_ready(const char *tag)
131	{
132	  struct circular_buf *rx_ring = (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
133	  uint32_t rd_ptr = rx_ring->read_idx_mirror;
134	  uint32_t wr_ptr = rx_ring->write_idx_mirror;
135	  long buf_size = rx_ring->buffer_size;
136	
137	  if (!sf32lb52_bt_rx_ring_valid(rx_ring))
138	    {
139	      syslog(LOG_WARNING,
140	             "%s rx ring invalid: buf=%ld expected=%lu rd=%08lx wr=%08lx\n",
141	             tag,
142	             buf_size,
143	             (unsigned long)SF32LB52_BT_RING_DATA_SIZE,
144	             (unsigned long)rd_ptr,
145	             (unsigned long)wr_ptr);
146	      return false;
147	    }
148	
149	  return true;
150	}
