176	static void sf32lb52_bt_prepare_stack_nvds(void)
177	{
178	  struct sf32lb52_bt_nvds_mem_init_s *nvds;
179	  const uint8_t *defaults;
180	  size_t defaults_len;
181	
182	  if (HAL_LXT_DISABLED())
183	    {
184	      defaults = g_sf32lb52_bt_nvds_default_rc10k;
185	      defaults_len = sizeof(g_sf32lb52_bt_nvds_default_rc10k);
186	    }
187	  else
188	    {
189	      defaults = g_sf32lb52_bt_nvds_default_lxt32k;
190	      defaults_len = sizeof(g_sf32lb52_bt_nvds_default_lxt32k);
191	    }
192	
193	  HAL_HPAON_WakeCore(CORE_ID_LCPU);
194	
195	  nvds = (struct sf32lb52_bt_nvds_mem_init_s *)SF32LB52_BT_NVDS_BUF_START;
196	  memset((void *)SF32LB52_BT_NVDS_BUF_START, 0, SF32LB52_BT_NVDS_BUF_SIZE);
197	  nvds->pattern = SF32LB52_BT_NVDS_PATTERN;
198	  nvds->used_mem = defaults_len;
199	  nvds->writting = 0;
200	  memcpy((void *)(nvds + 1), defaults, defaults_len);
201	  sf32lb52_bt_clean_nvds_shared();
202	
203	  HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
204	}
