206	static size_t sf32lb52_bt_ring_data_len(uint32_t rd_ptr, uint32_t wr_ptr,
207	                                        uint32_t buffer_size)
208	{
209	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
210	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
211	  uint32_t rd_mirror = CB_GET_PTR_MIRROR(rd_ptr);
212	  uint32_t wr_mirror = CB_GET_PTR_MIRROR(wr_ptr);
213	
214	  if (rd_idx == wr_idx)
215	    {
216	      return rd_mirror == wr_mirror ? 0 : buffer_size;
217	    }
218	
219	  if (wr_idx > rd_idx)
220	    {
221	      return wr_idx - rd_idx;
222	    }
223	
224	  return buffer_size - (rd_idx - wr_idx);
225	}
226	
227	static size_t sf32lb52_bt_ring_space_len(uint32_t rd_ptr, uint32_t wr_ptr,
228	                                         uint32_t buffer_size)
229	{
230	  return buffer_size - sf32lb52_bt_ring_data_len(rd_ptr, wr_ptr,
231	                                                buffer_size);
232	}
233	
234	static uint32_t sf32lb52_bt_ring_advance(uint32_t ptr, size_t len,
235	                                         uint32_t buffer_size)
236	{
237	  uint32_t idx = CB_GET_PTR_IDX(ptr);
238	  uint32_t mirror = CB_GET_PTR_MIRROR(ptr);
239	
240	  idx += len;
241	  if (idx >= buffer_size)
242	    {
243	      idx -= buffer_size;
244	      mirror = ~mirror;
245	    }
246	
247	  return CB_MAKE_PTR_IDX_MIRROR(idx, mirror);
248	}
249	
250	static size_t sf32lb52_bt_ring_copy(uint8_t *dst,
251	                                    const struct circular_buf *rx_ring,
252	                                    uint32_t rd_ptr,
253	                                    size_t len)
254	{
255	  const uint8_t *pool = (const uint8_t *)(rx_ring + 1);
256	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
257	  size_t tail;
258	
259	  if (len == 0)
260	    {
261	      return 0;
262	    }
263	
264	  tail = rx_ring->buffer_size - rd_idx;
265	  if (tail >= len)
266	    {
267	      memcpy(dst, &pool[rd_idx], len);
268	      return len;
269	    }
270	
271	  memcpy(dst, &pool[rd_idx], tail);
272	  memcpy(&dst[tail], pool, len - tail);
273	  return len;
274	}
275	
276	static size_t sf32lb52_bt_ring_write(struct circular_buf *tx_ring,
277	                                     const uint8_t *src, size_t len)
278	{
279	  uint8_t *pool = (uint8_t *)(tx_ring + 1);
280	  uint32_t wr_ptr = tx_ring->write_idx_mirror;
281	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
282	  size_t space;
283	  size_t tail;
284	
285	  space = sf32lb52_bt_ring_space_len(tx_ring->read_idx_mirror,
286	                                     wr_ptr,
287	                                     tx_ring->buffer_size);
288	  if (space == 0)
289	    {
290	      return 0;
291	    }
292	
293	  if (len > space)
294	    {
295	      len = space;
296	    }
297	
298	  tail = tx_ring->buffer_size - wr_idx;
299	  if (tail >= len)
300	    {
301	      memcpy(&pool[wr_idx], src, len);
302	      up_clean_dcache((uintptr_t)&pool[wr_idx],
303	                      (uintptr_t)&pool[wr_idx] + len);
304	    }
305	  else
306	    {
307	      memcpy(&pool[wr_idx], src, tail);
308	      memcpy(pool, &src[tail], len - tail);
309	      up_clean_dcache((uintptr_t)&pool[wr_idx],
310	                      (uintptr_t)&pool[wr_idx] + tail);
311	      up_clean_dcache((uintptr_t)pool,
312	                      (uintptr_t)pool + len - tail);
313	    }
314	
315	  tx_ring->write_idx_mirror = sf32lb52_bt_ring_advance(wr_ptr, len,
316	                                                       tx_ring->buffer_size);
317	  up_clean_dcache((uintptr_t)tx_ring,
318	                  (uintptr_t)tx_ring + sizeof(*tx_ring));
319	  __DSB();
320	
321	  return len;
322	}
323	
324	static size_t sf32lb52_bt_tx_pending(struct circular_buf *tx_ring,
325	                                     uint32_t *rd_ptr,
326	                                     uint32_t *wr_ptr)
327	{
328	  uint32_t rd;
329	  uint32_t wr;
330	
331	  up_invalidate_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
332	                       (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
333	                       sizeof(*tx_ring));
334	
335	  rd = tx_ring->read_idx_mirror;
336	  wr = tx_ring->write_idx_mirror;
337	
338	  if (rd_ptr != NULL)
339	    {
340	      *rd_ptr = rd;
341	    }
342	
343	  if (wr_ptr != NULL)
344	    {
345	      *wr_ptr = wr;
346	    }
347	
348	  return sf32lb52_bt_ring_data_len(rd, wr, tx_ring->buffer_size);
349	}
