409	static size_t sf32lb52_bt_tx_chunk_len(const uint8_t *data,
410	                                       size_t len,
411	                                       size_t offset)
412	{
413	  size_t remaining = len - offset;
414	
415	  if (SF32LB52_BT_TX_SPLIT_H4_TYPE && offset == 0 && remaining > 1)
416	    {
417	      return 1;
418	    }
419	
420	  return remaining;
421	}
