194	static uint16_t sf32lb52_bt_get_le16(const uint8_t *data)
195	{
196	  return (uint16_t)data[0] | ((uint16_t)data[1] << 8);
197	}
198	
199	static void sf32lb52_bt_put_le16(uint8_t *data, uint16_t value)
200	{
201	  data[0] = value & 0xff;
202	  data[1] = value >> 8;
203	}
204	
205	static ssize_t sf32lb52_bt_h4_packet_len(const uint8_t *data, size_t len)
206	{
207	  uint16_t payload_len;
208	
209	  if (len < H4_HEADER_SIZE)
210	    {
211	      return 0;
212	    }
213	
214	  switch (data[0])
215	    {
216	      case H4_EVT:
217	        if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s))
218	          {
219	            return 0;
220	          }
221	
222	        payload_len = data[H4_HEADER_SIZE + 1];
223	        return H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + payload_len;
224	
225	      case H4_ACL:
226	        if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_acl_hdr_s))
227	          {
228	            return 0;
229	          }
230	
231	        payload_len = sf32lb52_bt_get_le16(&data[H4_HEADER_SIZE + 2]);
232	        return H4_HEADER_SIZE + sizeof(struct bt_hci_acl_hdr_s) + payload_len;
233	
234	      case H4_ISO:
235	        if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_iso_hdr_s))
236	          {
237	            return 0;
238	          }
239	
240	        payload_len = sf32lb52_bt_get_le16(&data[H4_HEADER_SIZE + 2]) & 0x3fff;
241	        return H4_HEADER_SIZE + sizeof(struct bt_hci_iso_hdr_s) + payload_len;
242	
243	      default:
244	        return -EINVAL;
245	    }
246	}
247	
248	static void sf32lb52_bt_normalize_event(uint8_t *data, size_t len)
249	{
250	  uint16_t opcode;
251	
252	  if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + 4 ||
253	      data[0] != H4_EVT)
254	    {
255	      return;
256	    }
257	
258	  if (data[1] == BT_HCI_EVT_CMD_COMPLETE && data[2] >= 4)
259	    {
260	      opcode = sf32lb52_bt_get_le16(&data[4]);
261	      if (opcode == BT_HCI_OP_RESET && data[6] != SF32LB52_HCI_STATUS_SUCCESS)
262	        {
263	          data[6] = SF32LB52_HCI_STATUS_SUCCESS;
264	        }
265	    }
266	  else if (data[1] == BT_HCI_EVT_CMD_STATUS && data[2] >= 4)
267	    {
268	      opcode = sf32lb52_bt_get_le16(&data[5]);
269	      if (opcode == BT_HCI_OP_RESET && data[3] != SF32LB52_HCI_STATUS_SUCCESS)
270	        {
271	          data[3] = SF32LB52_HCI_STATUS_SUCCESS;
272	        }
273	    }
274	}
275	
276	static int sf32lb52_bt_forward_packet(struct sf32lb52_bt_priv_s *priv,
277	                                      uint8_t *data, size_t len)
278	{
279	  enum bt_buf_type_e type;
280	  int ret;
281	
282	  if (len <= H4_HEADER_SIZE)
283	    {
284	      return -EINVAL;
285	    }
286	
287	  switch (data[0])
288	    {
289	      case H4_EVT:
290	        #if SF32LB52_BT_NORMALIZE_RESET_STATUS
291	          sf32lb52_bt_normalize_event(data, len);
292	        #endif
293	        type = BT_EVT;
294	        break;
295	
296	      case H4_ACL:
297	        type = BT_ACL_IN;
298	        break;
299	
300	      case H4_ISO:
301	        type = BT_ISO_IN;
302	        break;
303	
304	      default:
305	        return -EINVAL;
306	    }
307	
308	  ret = bt_netdev_receive(&priv->drv,
309	                          type,
310	                          (void *)&data[H4_HEADER_SIZE],
311	                          len - H4_HEADER_SIZE);
312	  if (ret < 0)
313	    {
314	      wlerr("Failed to receive HCI packet: %d\n", ret);
315	    }
316	
317	  return ret;
318	}
