360	static bool sf32lb52_bt_emulate_cmd(struct sf32lb52_bt_priv_s *priv,
361	                                    uint16_t opcode, int *ret)
362	{
363	  uint8_t params[SF32LB52_HCI_MAX_CMD_COMPLETE_RPLEN];
364	
365	  switch (opcode)
366	    {
367	      case BT_HCI_OP_READ_SUPPORTED_COMMANDS:
368	        memset(params, 0, sizeof(params));
369	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
370	        params[1 + 27] = 1 << 7;
371	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params,
372	                                              SF32LB52_HCI_READ_COMMANDS_RPLEN);
373	        return true;
374	
375	      case BT_HCI_OP_LE_RAND:
376	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
377	        arc4random_buf(&params[1], SF32LB52_HCI_RAND_RPLEN - 1);
378	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params,
379	                                              SF32LB52_HCI_RAND_RPLEN);
380	        return true;
381	
382	      case BT_HCI_OP_READ_LOCAL_EXT_FEATURES:
383	        memset(params, 0, 11);
384	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
385	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 11);
386	        return true;
387	
388	      case BT_HCI_OP_READ_BUFFER_SIZE:
389	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
390	        sf32lb52_bt_put_le16(&params[1], 0x00fb);
391	        params[3] = 0;
392	        sf32lb52_bt_put_le16(&params[4], 4);
393	        sf32lb52_bt_put_le16(&params[6], 0);
394	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 8);
395	        return true;
396	
397	      case BT_HCI_OP_LE_READ_BUFFER_SIZE:
398	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
399	        sf32lb52_bt_put_le16(&params[1], 0x00fb);
400	        params[3] = 4;
401	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 4);
402	        return true;
403	
404	      case BT_HCI_OP_LE_READ_LOCAL_FEATURES:
405	        memset(params, 0, 9);
406	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
407	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 9);
408	        return true;
409	
410	      case BT_HCI_OP_LE_READ_MAX_DATA_LEN:
411	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
412	        sf32lb52_bt_put_le16(&params[1], 0x00fb);
413	        sf32lb52_bt_put_le16(&params[3], 0x0148);
414	        sf32lb52_bt_put_le16(&params[5], 0x00fb);
415	        sf32lb52_bt_put_le16(&params[7], 0x0148);
416	        *ret = sf32lb52_bt_synth_cmd_complete(priv, opcode, params, 9);
417	        return true;
418	
419	      case BT_HCI_OP_LE_READ_MAX_ADV_DATA_LEN:
420	        params[0] = SF32LB52_HCI_STATUS_SUCCESS;
