237	static ssize_t uart_bth4_read(FAR struct file *filep,
238	                              FAR char *buffer,
239	                              size_t buflen)
240	{
241	  FAR struct inode *inode = filep->f_inode;
242	  FAR struct uart_bth4_s *dev = inode->i_private;
243	  irqstate_t flags;
244	  ssize_t nread;
245	
246	  flags = spin_lock_irqsave(&dev->lock);
247	
248	  for (; ; )
249	    {
250	      nread = circbuf_read(&dev->circbuf, buffer, buflen);
251	      if (nread != 0 || (filep->f_oflags & O_NONBLOCK))
252	        {
253	          break;
254	        }
255	
256	      while (circbuf_is_empty(&dev->circbuf))
257	        {
258	          spin_unlock_irqrestore(&dev->lock, flags);
259	          nxsem_wait_uninterruptible(&dev->recvsem);
260	          flags = spin_lock_irqsave(&dev->lock);
261	        }
262	    }
263	
264	  spin_unlock_irqrestore(&dev->lock, flags);
265	  return nread;
266	}
267	
268	static ssize_t uart_bth4_write(FAR struct file *filep,
269	                               FAR const char *buffer,
270	                               size_t buflen)
271	{
272	  FAR struct inode *inode = filep->f_inode;
273	  FAR struct uart_bth4_s *dev = inode->i_private;
274	  FAR union bt_hdr_u *hdr;
275	  enum bt_buf_type_e type;
276	  size_t reserved;
277	  uint8_t *data;
278	  size_t pktlen;
279	  size_t hdrlen;
280	  int ret;
281	
282	  ret = nxmutex_lock(&dev->sendlock);
283	  if (ret < 0)
284	    {
285	      return ret;
286	    }
287	
288	  if (dev->drv->head_reserve < H4_HEADER_SIZE)
289	    {
290	      reserved = H4_HEADER_SIZE;
291	    }
292	  else
293	    {
294	      reserved = dev->drv->head_reserve;
295	    }
296	
297	  data = dev->sendbuf + reserved;
298	
299	  if (dev->sendlen + buflen > CONFIG_UART_BTH4_TXBUFSIZE - reserved)
300	    {
301	      ret = -E2BIG;
302	      goto err;
303	    }
304	
305	  memcpy(data - H4_HEADER_SIZE + dev->sendlen,
306	         buffer, buflen);
307	  dev->sendlen += buflen;
308	
309	  hdr = (FAR union bt_hdr_u *)data;
310	
311	  for (; ; )
312	    {
313	      switch (*(data - H4_HEADER_SIZE))
314	        {
315	          case H4_CMD:
316	            hdrlen = sizeof(struct bt_hci_cmd_hdr_s);
317	            pktlen = hdr->cmd.param_len;
318	            type = BT_CMD;
319	            break;
320	          case H4_ACL:
321	            hdrlen = sizeof(struct bt_hci_acl_hdr_s);
322	            pktlen = hdr->acl.len;
323	            type = BT_ACL_OUT;
324	            break;
325	          case H4_ISO:
326	            hdrlen = sizeof(struct bt_hci_iso_hdr_s);
327	            pktlen = hdr->iso.len;
328	            type = BT_ISO_OUT;
329	            break;
330	          default:
331	            ret = -EINVAL;
332	            goto err;
333	        }
334	
335	      /* Reassembly is incomplete ? */
336	
337	      hdrlen += H4_HEADER_SIZE;
338	
339	      if (dev->sendlen < hdrlen)
340	        {
341	          goto out;
342	        }
343	
344	      pktlen += hdrlen;
345	      if (dev->sendlen < pktlen)
346	        {
347	          goto out;
348	        }
349	
350	      /* Got the full packet, send out */
351	
352	      ret = dev->drv->send(dev->drv, type,
353	                           data, pktlen - H4_HEADER_SIZE);
354	      if (ret < 0)
355	        {
356	          goto err;
357	        }
358	
359	      dev->sendlen -= pktlen;
360	      if (dev->sendlen == 0)
361	        {
362	          goto out;
363	        }
364	
365	      memmove(data - H4_HEADER_SIZE,
366	              dev->sendbuf + pktlen, dev->sendlen);
367	    }
368	
369	err:
370	  dev->sendlen = 0;
371	out:
372	  nxmutex_unlock(&dev->sendlock);
373	  return ret < 0 ? ret : buflen;
374	}
