   357	static int sf32lb52_bt_wait_tx_idle(struct circular_buf *tx_ring)
   358	{
   359	  uint32_t start_time = HAL_GetTick();
   360	  uint32_t tick_count = 0;
   361	  uint32_t rd_ptr = 0;
   362	  uint32_t wr_ptr = 0;
   363	
   364	  while (sf32lb52_bt_tx_pending(tx_ring, &rd_ptr, &wr_ptr) > 0)
   365	    {
   366	      sf32lb52_bt_trigger_tx();
   367	
   368	      if (HAL_GetTick() != start_time)
   369	        {
   370	          tick_count++;
   371	          start_time = HAL_GetTick();
   372	        }
   373	
   374	      if (tick_count >= 100)
   375	        {
   376	          syslog(LOG_ERR,
   377	                 "sf32lb52 bt tx busy: rd=%08lx wr=%08lx\n",
   378	                 (unsigned long)rd_ptr,
   379	                 (unsigned long)wr_ptr);
   380	          return -ETIMEDOUT;
   381	        }
   382	
   383	      usleep(1000);
   384	    }
   385	
   386	  return OK;
   387	}
