   109	static inline void uart_bth4_post(FAR sem_t *sem)
   110	{
   111	  int semcount;
   112	
   113	  nxsem_get_value(sem, &semcount);
   114	  if (semcount < 1)
   115	    {
   116	      nxsem_post(sem);
   117	    }
   118	}
   119	
   120	static void uart_bth4_pollnotify(FAR struct uart_bth4_s *dev,
   121	                                 pollevent_t eventset)
   122	{
   123	  poll_notify(dev->fds, CONFIG_UART_BTH4_NPOLLWAITERS, eventset);
   124	
   125	  if ((eventset & POLLIN) != 0)
   126	    {
   127	      uart_bth4_post(&dev->recvsem);
   128	    }
   129	}
   130	
   131	static int uart_bth4_receive(FAR struct bt_driver_s *drv,
   132	                             enum bt_buf_type_e type,
   133	                             FAR void *buffer, size_t buflen)
   134	{
   135	  FAR struct uart_bth4_s *dev = drv->priv;
   136	  int ret = buflen;
   137	  irqstate_t flags;
   138	  uint8_t htype;
   139	
   140	  flags = spin_lock_irqsave_nopreempt(&dev->lock);
   141	
   142	  if (circbuf_space(&dev->circbuf) >=
   143	      buflen + H4_HEADER_SIZE)
   144	    {
   145	      if (type == BT_EVT)
   146	        {
   147	          htype = H4_EVT;
   148	        }
   149	      else if (type == BT_ACL_IN)
   150	        {
   151	          htype = H4_ACL;
   152	        }
   153	      else if (type == BT_ISO_IN)
   154	        {
   155	          htype = H4_ISO;
   156	        }
   157	      else
   158	        {
   159	          ret = -EINVAL;
   160	        }
   161	
   162	      if (ret >= 0)
   163	        {
   164	          circbuf_write(&dev->circbuf, &htype, H4_HEADER_SIZE);
   165	          circbuf_write(&dev->circbuf, buffer, buflen);
   166	          uart_bth4_pollnotify(dev, POLLIN);
   167	        }
   168	    }
   169	  else
   170	    {
   171	      ret = -ENOMEM;
   172	    }
   173	
   174	  spin_unlock_irqrestore_nopreempt(&dev->lock, flags);
   175	  return ret;
   176	}
   177	
   178	static int uart_bth4_open(FAR struct file *filep)
   179	{
   180	  FAR struct inode *inode = filep->f_inode;
   181	  FAR struct uart_bth4_s *dev = inode->i_private;
   182	  int ret;
   183	  uint8_t tmp;
   184	
   185	  ret = nxmutex_lock(&dev->openlock);
   186	  if (ret < 0)
   187	    {
   188	      return ret;
   189	    }
   190	
   191	  tmp = dev->refcnt + 1;
   192	  if (tmp == 0)
   193	    {
   194	      nxmutex_unlock(&dev->openlock);
   195	      return -EMFILE;
   196	    }
   197	
   198	  if (tmp == 1)
   199	    {
   200	      ret = dev->drv->open(dev->drv);
   201	      if (ret < 0)
   202	        {
   203	          nxmutex_unlock(&dev->openlock);
   204	          return ret;
   205	        }
   206	
   207	      dev->sendlen = 0;
   208	    }
   209	
   210	  dev->refcnt = tmp;
   211	  nxmutex_unlock(&dev->openlock);
   212	
   213	  return OK;
   214	}
   215	
   216	static int uart_bth4_close(FAR struct file *filep)
   217	{
   218	  FAR struct inode *inode = filep->f_inode;
   219	  FAR struct uart_bth4_s *dev = inode->i_private;
   220	
   221	  nxmutex_lock(&dev->openlock);
   222	  if (dev->refcnt > 1)
   223	    {
   224	      dev->refcnt--;
   225	      nxmutex_unlock(&dev->openlock);
   226	      return OK;
   227	    }
   228	
   229	  dev->refcnt = 0;
   230	  dev->drv->close(dev->drv);
   231	  uart_bth4_pollnotify(dev, POLLIN | POLLOUT);
   232	  nxmutex_unlock(&dev->openlock);
   233	
   234	  return OK;
   235	}
   236	
   237	static ssize_t uart_bth4_read(FAR struct file *filep,
   238	                              FAR char *buffer,
   239	                              size_t buflen)
   240	{
   241	  FAR struct inode *inode = filep->f_inode;
   242	  FAR struct uart_bth4_s *dev = inode->i_private;
   243	  irqstate_t flags;
   244	  ssize_t nread;
   245	
   246	  flags = spin_lock_irqsave(&dev->lock);
   247	
   248	  for (; ; )
   249	    {
   250	      nread = circbuf_read(&dev->circbuf, buffer, buflen);
   251	      if (nread != 0 || (filep->f_oflags & O_NONBLOCK))
   252	        {
   253	          break;
   254	        }
   255	
   256	      while (circbuf_is_empty(&dev->circbuf))
   257	        {
   258	          spin_unlock_irqrestore(&dev->lock, flags);
   259	          nxsem_wait_uninterruptible(&dev->recvsem);
   260	          flags = spin_lock_irqsave(&dev->lock);
   261	        }
   262	    }
   263	
   264	  spin_unlock_irqrestore(&dev->lock, flags);
   265	  return nread;
   266	}
   267	
   268	static ssize_t uart_bth4_write(FAR struct file *filep,
   269	                               FAR const char *buffer,
   270	                               size_t buflen)
   271	{
   272	  FAR struct inode *inode = filep->f_inode;
   273	  FAR struct uart_bth4_s *dev = inode->i_private;
   274	  FAR union bt_hdr_u *hdr;
   275	  enum bt_buf_type_e type;
   276	  size_t reserved;
   277	  uint8_t *data;
   278	  size_t pktlen;
   279	  size_t hdrlen;
   280	  int ret;
   281	
   282	  ret = nxmutex_lock(&dev->sendlock);
   283	  if (ret < 0)
   284	    {
   285	      return ret;
   286	    }
   287	
   288	  if (dev->drv->head_reserve < H4_HEADER_SIZE)
   289	    {
   290	      reserved = H4_HEADER_SIZE;
   291	    }
   292	  else
   293	    {
   294	      reserved = dev->drv->head_reserve;
   295	    }
   296	
   297	  data = dev->sendbuf + reserved;
   298	
   299	  if (dev->sendlen + buflen > CONFIG_UART_BTH4_TXBUFSIZE - reserved)
   300	    {
   301	      ret = -E2BIG;
   302	      goto err;
   303	    }
   304	
   305	  memcpy(data - H4_HEADER_SIZE + dev->sendlen,
   306	         buffer, buflen);
   307	  dev->sendlen += buflen;
   308	
   309	  hdr = (FAR union bt_hdr_u *)data;
   310	
   311	  for (; ; )
   312	    {
   313	      switch (*(data - H4_HEADER_SIZE))
   314	        {
   315	          case H4_CMD:
   316	            hdrlen = sizeof(struct bt_hci_cmd_hdr_s);
   317	            pktlen = hdr->cmd.param_len;
   318	            type = BT_CMD;
   319	            break;
   320	          case H4_ACL:
   321	            hdrlen = sizeof(struct bt_hci_acl_hdr_s);
   322	            pktlen = hdr->acl.len;
   323	            type = BT_ACL_OUT;
   324	            break;
   325	          case H4_ISO:
   326	            hdrlen = sizeof(struct bt_hci_iso_hdr_s);
   327	            pktlen = hdr->iso.len;
   328	            type = BT_ISO_OUT;
   329	            break;
   330	          default:
   331	            ret = -EINVAL;
   332	            goto err;
   333	        }
   334	
   335	      /* Reassembly is incomplete ? */
   336	
   337	      hdrlen += H4_HEADER_SIZE;
   338	
   339	      if (dev->sendlen < hdrlen)
   340	        {
   341	          goto out;
   342	        }
   343	
   344	      pktlen += hdrlen;
   345	      if (dev->sendlen < pktlen)
   346	        {
   347	          goto out;
   348	        }
   349	
   350	      /* Got the full packet, send out */
   351	
   352	      ret = dev->drv->send(dev->drv, type,
   353	                           data, pktlen - H4_HEADER_SIZE);
   354	      if (ret < 0)
   355	        {
   356	          goto err;
   357	        }
   358	
   359	      dev->sendlen -= pktlen;
   360	      if (dev->sendlen == 0)
   361	        {
   362	          goto out;
   363	        }
   364	
   365	      memmove(data - H4_HEADER_SIZE,
   366	              dev->sendbuf + pktlen, dev->sendlen);
   367	    }
   368	
   369	err:
   370	  dev->sendlen = 0;
   371	out:
   372	  nxmutex_unlock(&dev->sendlock);
   373	  return ret < 0 ? ret : buflen;
   374	}
   375	
   376	static int uart_bth4_ioctl(FAR struct file *filep, int cmd,
   377	                           unsigned long arg)
   378	{
   379	  FAR struct inode *inode = filep->f_inode;
   380	  FAR struct uart_bth4_s *dev = inode->i_private;
   381	
   382	  if (!dev->drv->ioctl)
   383	    {
   384	      return -ENOTTY;
   385	    }
   386	
   387	  return dev->drv->ioctl(dev->drv, cmd, arg);
   388	}
   389	
   390	static int uart_bth4_poll(FAR struct file *filep, FAR struct pollfd *fds,
   391	                          bool setup)
   392	{
   393	  FAR struct inode *inode = filep->f_inode;
   394	  FAR struct uart_bth4_s *dev = inode->i_private;
   395	  pollevent_t eventset = 0;
   396	  irqstate_t flags;
   397	  int ret = 0;
   398	  int i;
   399	
   400	  flags = spin_lock_irqsave_nopreempt(&dev->lock);
   401	
   402	  if (setup)
   403	    {
   404	      for (i = 0; i < CONFIG_UART_BTH4_NPOLLWAITERS; i++)
   405	        {
   406	          /* Find an available slot */
   407	
   408	          if (!dev->fds[i])
   409	            {
   410	              /* Bind the poll structure and this slot */
   411	
   412	              dev->fds[i] = fds;
   413	              fds->priv   = &dev->fds[i];
   414	              break;
   415	            }
   416	        }
   417	
   418	      if (i >= CONFIG_UART_BTH4_NPOLLWAITERS)
   419	        {
   420	          fds->priv = NULL;
   421	          ret = -EBUSY;
   422	        }
   423	
   424	      if (!circbuf_is_empty(&dev->circbuf))
   425	        {
   426	          eventset |= POLLIN;
   427	        }
   428	
   429	      eventset |= POLLOUT;
   430	
   431	      poll_notify(&fds, 1, eventset);
   432	    }
   433	  else if (fds->priv != NULL)
   434	    {
   435	      for (i = 0; i < CONFIG_UART_BTH4_NPOLLWAITERS; i++)
   436	        {
   437	          if (fds == dev->fds[i])
   438	            {
   439	              dev->fds[i] = NULL;
   440	              fds->priv = NULL;
   441	              break;
   442	            }
   443	        }
   444	    }
   445	
   446	  spin_unlock_irqrestore_nopreempt(&dev->lock, flags);
   447	  return ret;
   448	}
