663	static int sf32lb52_bt_open(struct bt_driver_s *drv)
664	{
665	  int ret;
666	
667	  (void)drv;
668	
669	  g_sf32lb52_bt_priv.rxlen = 0;
670	  g_sf32lb52_bt_priv.drop_rx_until_tx = true;
671	
672	  ret = sf32lb52_bt_controller_init();
673	  if (ret < 0)
674	    {
675	      return ret;
676	    }
677	
678	  ret = sf32lb52_hci_register_callback(sf32lb52_bt_recv_cb);
679	  if (ret < 0)
680	    {
681	      return ret;
682	    }
683	
684	  return OK;
