683	int sf32lb52_bt_controller_deinit(void)
684	{
685	  int ret;
686	
687	  if (g_sf32lb52_bt_status == SF32LB52_BT_STATUS_ENABLED)
688	    {
689	      ret = sf32lb52_bt_controller_disable();
690	      if (ret < 0)
691	        {
692	          return ret;
693	        }
694	    }
695	
696	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_INITED)
697	    {
698	      return -EPERM;
699	    }
700	
701	  g_sf32lb52_bt_env.queue_open = false;
702	  g_sf32lb52_bt_env.rx_work_pending = false;
703	  g_sf32lb52_bt_env.rx_worker_running = false;
704	  if (!work_available(&g_sf32lb52_bt_env.rx_work))
705	    {
706	      ret = work_cancel_sync(HPWORK, &g_sf32lb52_bt_env.rx_work);
707	      if (ret < 0 && ret != -ENOENT)
708	        {
709	          return ret;
710	        }
711	    }
712	
713	  ret = ipc_queue_deinit(g_sf32lb52_bt_env.ipc_port);
714	  if (ret < 0)
715	    {
716	      return ret;
717	    }
718	
719	  memset(&g_sf32lb52_bt_env, 0, sizeof(g_sf32lb52_bt_env));
720	  g_sf32lb52_bt_env.ipc_port = IPC_QUEUE_INVALID_HANDLE;
721	  g_sf32lb52_bt_status = SF32LB52_BT_STATUS_IDLE;
722	  return OK;
723	}
