476	
477	static int sf32lb52_bt_recv_cb(uint8_t *data, uint16_t len)
478	{
479	  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
480	  ssize_t packet_len;
481	  int ret;
482	
483	  if (data == NULL || len == 0)
484	    {
485	      return -EINVAL;
486	    }
487	
488	  if (priv->drop_rx_until_tx)
489	    {
490	      return OK;
491	    }
492	
493	  if (priv->rxlen + len > sizeof(priv->rxbuf))
494	    {
495	      syslog(LOG_ERR,
496	             "sf32lb52 bth4 rx overflow: pending=%lu incoming=%u\n",
497	             (unsigned long)priv->rxlen,
498	             len);
499	      priv->rxlen = 0;
500	    }
501	
502	  memcpy(&priv->rxbuf[priv->rxlen], data, len);
503	  priv->rxlen += len;
504	
505	#if SF32LB52_BT_TRACE
506	  if (priv->rxbuf[0] != H4_ACL || SF32LB52_BT_TRACE_ACL)
507	    {
508	      syslog(LOG_INFO,
509	             "sf32lb52 bth4 recv: len=%u pending=%lu first=%02x\n",
510	             len, (unsigned long)priv->rxlen, priv->rxbuf[0]);
511	    }
512	#endif
513	
514	  ret = OK;
515	
516	  while (priv->rxlen > 0)
517	    {
518	      packet_len = sf32lb52_bt_h4_packet_len(priv->rxbuf, priv->rxlen);
519	      if (packet_len == 0)
520	        {
521	          break;
522	        }
523	
524	      if (packet_len < 0)
525	        {
526	          syslog(LOG_WARNING,
527	                 "sf32lb52 bth4 drop invalid h4 type=%02x pending=%lu\n",
528	                 priv->rxbuf[0],
529	                 (unsigned long)priv->rxlen);
530	          memmove(priv->rxbuf, &priv->rxbuf[1], priv->rxlen - 1);
531	          priv->rxlen--;
532	          ret = -EINVAL;
533	          continue;
534	        }
535	
536	      if ((size_t)packet_len > priv->rxlen)
537	        {
538	          break;
539	        }
540	
541	      ret = sf32lb52_bt_forward_packet(priv, priv->rxbuf,
542	                   (size_t)packet_len);
543	
544	      priv->rxlen -= (size_t)packet_len;
545	      if (priv->rxlen > 0)
546	        {
547	          memmove(priv->rxbuf,
548	                  &priv->rxbuf[packet_len],
549	                  priv->rxlen);
550	        }
551	    }
552	
553	  return ret;
554	}
555	
556	static int sf32lb52_bt_send(struct bt_driver_s *drv,
557	                            enum bt_buf_type_e type,
558	                            void *data, size_t len)
559	{
560	  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
561	  uint8_t *hdr = (uint8_t *)data - drv->head_reserve;
562	  uint16_t opcode;
563	  int ret;
564	
565	  switch (type)
566	    {
567	      case BT_CMD:
568	        *hdr = H4_CMD;
569	        break;
570	      case BT_ACL_OUT:
571	        *hdr = H4_ACL;
572	        break;
573	      case BT_ISO_OUT:
574	        *hdr = H4_ISO;
575	        break;
576	      default:
577	        return -EINVAL;
578	    }
579	
580	  if (type == BT_CMD && len >= sizeof(struct bt_hci_cmd_hdr_s))
581	    {
582	      opcode = sf32lb52_bt_get_le16(data);
583	
584	  #if SF32LB52_BT_TRACE
585	    syslog(LOG_INFO,
586	            "sf32lb52 bth4 hci tx: opcode=0x%04x len=%lu\n",
587	            opcode, (unsigned long)len);
588	    #endif
589	
590	  #if SF32LB52_BT_COMPAT_BR_INIT
591	    if (opcode == BT_HCI_OP_WRITE_LOCAL_NAME)
592	      {
593	        syslog(LOG_INFO,
594	               "sf32lb52 bth4 compat: synth BR init opcode=0x%04x\n",
595	               opcode);
596	        ret = sf32lb52_bt_synth_status_complete(priv, opcode);
597	        return ret < 0 ? ret : len;
598	      }
599	    #endif
600	
601	  #if SF32LB52_BT_EMULATE_HCI
602	    if (sf32lb52_bt_emulate_cmd(priv, opcode, &ret))
603	    {
604	      return ret < 0 ? ret : len;
605	    }
606	    #endif
607	
608	  ret = sf32lb52_bt_ensure_controller_enabled(opcode);
609	      if (ret < 0)
610	        {
611	          return ret;
612	        }
613	    }
614	  else
615	    {
616	      ret = sf32lb52_bt_ensure_controller_enabled(0);
617	      if (ret < 0)
618	        {
619	          return ret;
620	        }
621	    }
622	
623	  priv->drop_rx_until_tx = false;
624	
625	  if (SF32LB52_BT_TRACE_ACL && type == BT_ACL_OUT)
626	    {
627	      syslog(LOG_INFO,
628	             "sf32lb52 bth4 tx: type=%u len=%lu h4=%02x acl=%02x %02x %02x %02x\n",
629	             (unsigned int)type,
630	             (unsigned long)(len + drv->head_reserve),
631	             hdr[0],
632	             len >= 1 ? hdr[1] : 0,
633	             len >= 2 ? hdr[2] : 0,
634	             len >= 3 ? hdr[3] : 0,
635	             len >= 4 ? hdr[4] : 0);
636	    }
637	
638	  ret = sf32lb52_host_send_packet(hdr, len + drv->head_reserve);
639	  if (ret < 0)
640	    {
641	      return ret;
642	    }
643	
644	  return len;
645	}
646	
647	static int sf32lb52_bt_ensure_controller_enabled(uint16_t opcode)
648	{
649	  int ret;
650	
651	  ret = sf32lb52_bt_controller_enable();
652	  if (ret < 0)
653	    {
654	      syslog(LOG_ERR,
655	             "sf32lb52 bth4 controller enable failed before opcode=0x%04x: %d\n",
656	             opcode,
657	             ret);
658	    }
659	
660	  return ret;
661	}
