707	int sf32lb52_bt_initialize(void)
708	{
709	  int ret;
710	
711	  ret = uart_bth4_register("/dev/ttyHCI0", &g_sf32lb52_bt_priv.drv);
712	  if (ret < 0 && ret != -EEXIST)
713	    {
714	      wlerr("Failed to register /dev/ttyHCI0: %d\n", ret);
715	      return ret;
716	    }
717	
718	  sf32lb52_bt_zblue_init_once();
719	
720	  return OK;
