   557	static int32_t sf32lb52_bt_rx_ind(ipc_queue_handle_t handle, size_t size)
   558	{
   559	  struct sf32lb52_bt_env_s *env = &g_sf32lb52_bt_env;
   560	  irqstate_t flags;
   561	  bool queue_work;
   562	  bool work_ready;
   563	  bool report_exit_window = false;
   564	
   565	  if (handle != env->ipc_port)
   566	    {
   567	      return -EINVAL;
   568	    }
   569	
   570	  if (!env->queue_open)
   571	    {
   572	      struct circular_buf *rx_ring = (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
   573	      #if SF32LB52_BT_TRACE
   574	            syslog(LOG_INFO, "sf32lb52 rx_ind (pre-open) wr=%08lx rd=%08lx\n",
   575	              (unsigned long)rx_ring->write_idx_mirror,
   576	              (unsigned long)rx_ring->read_idx_mirror);
   577	      #endif
   578	      return OK;
   579	    }
   580	
   581	  flags = enter_critical_section();
   582	  env->rx_work_pending = true;
   583	  work_ready = work_available(&env->rx_work);
   584	  queue_work = !env->rx_worker_running && work_ready;
   585	  if (queue_work)
   586	    {
   587	      env->rx_worker_running = true;
   588	      env->rx_exit_window_reported = false;
   589	    }
   590	  else if (!env->rx_worker_running && !work_ready &&
   591	           !env->rx_exit_window_reported)
   592	    {
   593	      env->rx_exit_window_reported = true;
   594	      report_exit_window = true;
   595	    }
   596	  leave_critical_section(flags);
   597	
   598	  if (report_exit_window)
   599	    {
   600	      syslog(LOG_WARNING, "sf32lb52 bt RX worker exit window hit\n");
   601	    }
   602	
   603	#if SF32LB52_BT_TRACE
   604	  {
   605	    struct circular_buf *rx_ring =
   606	        (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
   607	
   608	    up_invalidate_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
   609	                         (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
   610	                         sizeof(*rx_ring));
   611	
   612	    syslog(LOG_INFO,
   613	           "sf32lb52 rx_ind: size=%lu local=%08lx rd=%08lx wr=%08lx\n",
   614	           (unsigned long)size,
   615	           (unsigned long)env->rx_read_idx_mirror,
   616	           (unsigned long)rx_ring->read_idx_mirror,
   617	           (unsigned long)rx_ring->write_idx_mirror);
   618	  }
   619	#endif
   620	
   621	  if (queue_work)
   622	    {
   623	      int ret;
   624	
   625	      ret = work_queue(HPWORK, &env->rx_work, sf32lb52_bt_rx_worker,
   626	                       env, 0);
   627	      if (ret < 0)
   628	        {
   629	          flags = enter_critical_section();
   630	          env->rx_worker_running = false;
   631	          leave_critical_section(flags);
   632	
   633	          syslog(LOG_ERR, "sf32lb52 bt queue rx work failed: %d\n", ret);
   634	          return ret;
   635	        }
   636	    }
   637	
   638	  return OK;
   639	}
