   205	static ssize_t sf32lb52_bt_h4_packet_len(const uint8_t *data, size_t len)
   206	{
   207	  uint16_t payload_len;
   208	
   209	  if (len < H4_HEADER_SIZE)
   210	    {
   211	      return 0;
   212	    }
   213	
   214	  switch (data[0])
   215	    {
   216	      case H4_EVT:
   217	        if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s))
   218	          {
   219	            return 0;
   220	          }
   221	
   222	        payload_len = data[H4_HEADER_SIZE + 1];
   223	        return H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + payload_len;
   224	
   225	      case H4_ACL:
   226	        if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_acl_hdr_s))
   227	          {
   228	            return 0;
   229	          }
   230	
   231	        payload_len = sf32lb52_bt_get_le16(&data[H4_HEADER_SIZE + 2]);
   232	        return H4_HEADER_SIZE + sizeof(struct bt_hci_acl_hdr_s) + payload_len;
   233	
   234	      case H4_ISO:
   235	        if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_iso_hdr_s))
   236	          {
   237	            return 0;
   238	          }
   239	
   240	        payload_len = sf32lb52_bt_get_le16(&data[H4_HEADER_SIZE + 2]) & 0x3fff;
   241	        return H4_HEADER_SIZE + sizeof(struct bt_hci_iso_hdr_s) + payload_len;
   242	
   243	      default:
   244	        return -EINVAL;
   245	    }
   246	}
