   248	static void sf32lb52_bt_normalize_event(uint8_t *data, size_t len)
   249	{
   250	  uint16_t opcode;
   251	
   252	  if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + 4 ||
   253	      data[0] != H4_EVT)
   254	    {
   255	      return;
   256	    }
   257	
   258	  if (data[1] == BT_HCI_EVT_CMD_COMPLETE && data[2] >= 4)
   259	    {
   260	      opcode = sf32lb52_bt_get_le16(&data[4]);
   260	      opcode = sf32lb52_bt_get_le16(&data[4]);
   261	      if (opcode == BT_HCI_OP_RESET && data[6] != SF32LB52_HCI_STATUS_SUCCESS)
   262	        {
   263	          data[6] = SF32LB52_HCI_STATUS_SUCCESS;
   264	        }
   265	    }
   266	  else if (data[1] == BT_HCI_EVT_C…2261 tokens truncated…O,
   509	             "sf32lb52 bth4 recv: len=%u pending=%lu first=%02x\n",
   510	             len, (unsigned long)priv->rxlen, priv->rxbuf[0]);
   511	    }
   512	#endif
   513	
   514	  ret = OK;
   515	
   516	  while (priv->rxlen > 0)
   517	    {
   518	      packet_len = sf32lb52_bt_h4_packet_len(priv->rxbuf, priv->rxlen);
   519	      if (packet_len == 0)
   520	        {
   521	          break;
   522	        }
   523	
   524	      if (packet_len < 0)
   525	        {
   526	          syslog(LOG_WARNING,
   527	                 "sf32lb52 bth4 drop invalid h4 type=%02x pending=%lu\n",
   528	                 priv->rxbuf[0],
   529	                 (unsigned long)priv->rxlen);
   530	          memmove(priv->rxbuf, &priv->rxbuf[1], priv->rxlen - 1);
   531	          priv->rxlen--;
   532	          ret = -EINVAL;
   533	          continue;
   534	        }
   535	
   536	      if ((size_t)packet_len > priv->rxlen)
   537	        {
   538	          break;
   539	        }
   540	
   541	      ret = sf32lb52_bt_forward_packet(priv, priv->rxbuf,
   542	                   (size_t)packet_len);
   543	
   544	      priv->rxlen -= (size_t)packet_len;
   545	      if (priv->rxlen > 0)
   546	        {
   547	          memmove(priv->rxbuf,
   548	                  &priv->rxbuf[packet_len],
   549	                  priv->rxlen);
   550	        }
   551	    }
   552	
   553	  return ret;
   554	}
