   219	static void bt_sal_hci_transport_recv(void)
   220	{
   221	    struct h4_data* h4 = bt_dev->data;
   222	    static uint8_t frame[1026];
   223	    struct net_buf* buf;
   224	    size_t buf_tailroom;
   225	    size_t buf_add_len;
   226	    ssize_t len;
   227	    const uint8_t* frame_start = frame;
   228	    static ssize_t frame_size = 0;
   229	
   230	    len = read(h4->fd, frame + frame_size, sizeof(frame) - frame_size);
   231	    if (len < 0) {
   232	        BT_LOGE("Reading hci failed, errno %d", errno);
   233	        close(h4->fd);
   234	        h4->fd = -1;
   235	        return;
   236	    }
   237	
   238	    frame_size += len;
   239	
   240	    while (frame_size > 0) {
   241	        const uint8_t* buf_add;
   242	        const uint8_t packet_type = frame_start[0];
   243	        const int32_t decoded_len = hci_packet_complete(frame_start, frame_size);
   244	
   245	        if (decoded_len == -1) {
   246	            BT_LOGE("HCI Packet type is invalid, length could not be decoded");
   247	            frame_size = 0; /* Drop buffer */
   248	            break;
   249	        }
   250	
   251	        if (decoded_len == 0) {
   252	            if (frame_size == sizeof(frame)) {
   253	                BT_LOGE("HCI Packet is too big for frame");
   254	                frame_size = 0; /* Drop buffer */
   255	                break;
   256	            }
   257	            if (frame_start != frame) {
   258	                memmove(frame, frame_start, frame_size);
   259	            }
   260	            /* Read more */
   261	            break;
   262	        }
   263	
   264	        buf_add = frame_start + sizeof(packet_type);
   265	        buf_add_len = decoded_len - sizeof(packet_type);
   266	
   267	        buf = get_rx(frame_start);
   268	
   269	        frame_size -= decoded_len;
   270	        frame_start += decoded_len;
   271	
   272	        if (!buf) {
   273	            BT_LOGD("Discard adv report due to insufficient buf");
   274	            continue;
   275	        }
   276	
   277	        buf_tailroom = net_buf_tailroom(buf);
   278	        if (buf_tailroom < buf_add_len) {
   279	            BT_LOGE("Not enough space in buffer %zu/%zu", buf_add_len,
   280	                buf_tailroom);
   281	            net_buf_unref(buf);
   282	            continue;
   283	        }
   284	
   285	        net_buf_add_mem(buf, buf_add, buf_add_len);
   286	
   287	        h4_data_dump("BT RX", packet_type, buf->data, buf_add_len);
   288	        h4->recv(bt_dev, buf, h4->hci_data);
   289	    }
   290	}
