   354	static int h4_send(const struct device* dev, struct net_buf* buf)
   355	{
   356	    int len;
   357	    int ret;
   358	    struct h4_data* h4 = bt_dev->data;
   359	
   360	    switch (bt_buf_get_type(buf)) {
   361	    case BT_BUF_ACL_OUT:
   362	        net_buf_push_u8(buf, BT_HCI_H4_ACL);
   363	        break;
   364	    case BT_BUF_CMD:
   365	        net_buf_push_u8(buf, BT_HCI_H4_CMD);
   366	        break;
   367	    case BT_BUF_ISO_OUT:
   368	        if (IS_ENABLED(CONFIG_BT_ISO)) {
   369	            net_buf_push_u8(buf, BT_HCI_H4_ISO);
   370	            break;
   371	        }
   372	    default:
   373	        BT_LOGE("Unknown buffer type");
   374	        return -EINVAL;
   375	    }
   376	
   377	    h4_data_dump("BT TX", buf->data[0], buf->data, buf->len);
   378	
   379	    len = buf->len;
   380	    ret = h4_send_data(h4->fd, buf->data, buf->len);
   381	    if (ret != len) {
   382	        BT_LOGE("H4: Failed to send %u bytes: %d", len, ret);
   383	        ret = -EINVAL;
   384	    }
   385	
   386	    net_buf_unref(buf);
   387	
   388	    return ret < 0 ? ret : 0;
   389	}
