   326	static int h4_open(const struct device* dev, bt_hci_recv_t recv, void* hci_data)
   327	{
   328	    int fd;
   329	    struct h4_data* h4;
   330	
   331	    fd = open(CONFIG_BT_UART_ON_DEV_NAME, O_RDWR | O_BINARY | O_CLOEXEC);
   332	    if (fd < 0) {
   333	        BT_LOGE("H4: Failed to open %s: %d", CONFIG_BT_UART_ON_DEV_NAME, errno);
   334	        return fd;
   335	    }
   336	
   337	    h4 = dev->data;
   338	    h4->fd = fd;
   339	    h4->recv = recv;
   340	    h4->hci_data = hci_data;
   341	
   342	    bt_dev = dev;
   343	    BT_LOGE("H4: %s opened as fd:%d", CONFIG_BT_UART_ON_DEV_NAME, h4->fd);
   344	
   345	    hci_handle = service_loop_poll_fd(h4->fd, POLL_READABLE, hci_poll_recv, NULL);
   346	    if (!hci_handle) {
   347	        BT_LOGD("hci fd:%d add poll failed", h4->fd);
   348	        return -1;
   349	    }
   350	
   351	    return 0;
   352	}
