   466	static struct sf32lb52_bt_priv_s g_sf32lb52_bt_priv =
   467	{
   468	  .drv =
   469	    {
   470	      .head_reserve = H4_HEADER_SIZE,
   471	      .open         = sf32lb52_bt_open,
   472	      .send         = sf32lb52_bt_send,
   473	      .close        = sf32lb52_bt_close,
