   748	    }
   749	
   750	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_INITED)
   751	    {
   752	      return -EPERM;
   753	    }
   754	
   755	  sf32lb52_bt_prepare_stack_nvds();
   756	  HAL_LCPU_ASSERT_INFO_clear();
   757	
   758	  ret = lcpu_power_on();
   759	  if (ret != 0)
   760	    {
   761	      return -EIO;
   762	    }
