   866	  g_sf32lb52_bt_env.rx_work_pending = false;
   867	  g_sf32lb52_bt_env.rx_worker_running = false;
   868	  if (!work_available(&g_sf32lb52_bt_env.rx_work))
   869	    {
   870	      tmpret = work_cancel_sync(HPWORK, &g_sf32lb52_bt_env.rx_work);
   871	      if (tmpret < 0 && tmpret != -ENOENT && ret == OK)
