   562	  uint16_t opcode;
   563	  int ret;
   564	
   565	  switch (type)
   566	    {
   567	      case BT_CMD:
   568	        *hdr = H4_CMD;
   569	        break;
   570	      case BT_ACL_OUT:
   571	        *hdr = H4_ACL;
   572	        break;
   573	      case BT_ISO_OUT:
