   687	static void sf32lb52_bt_close(struct bt_driver_s *drv)
   688	{
   689	  int ret;
   690	
   691	  (void)drv;
   692	
   693	  g_sf32lb52_bt_priv.rxlen = 0;
   694	
   695	  /* Full deinit (not just disable) so that the next open re-initialises
   696	   * the IPC queue from a clean state.  Without deinit, controller_init
   697	   * is skipped on re-open (status != IDLE), and LCPU's ring-buffer
   698	   * read pointer (reset on power-on) diverges from HCPU's stale write
   699	   * pointer, causing all HCI commands to be silently dropped. */
   700	  ret = sf32lb52_bt_controller_deinit();
   701	  if (ret < 0)
   702	    {
   703	      wlerr("Failed to deinit HCI controller: %d\n", ret);
   704	    }
   705	}
