   741	int sf32lb52_bt_controller_enable(void)
   742	{
   743	  int ret;
   744	
   745	  if (g_sf32lb52_bt_status == SF32LB52_BT_STATUS_ENABLED)
   746	    {
   747	      return OK;
   748	    }
   749	
   750	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_INITED)
   751	    {
   752	      return -EPERM;
   753	    }
   754	
   755	  sf32lb52_bt_prepare_stack_nvds();
   756	  HAL_LCPU_ASSERT_INFO_clear();
   757	
   758	  ret = lcpu_power_on();
   759	  if (ret != 0)
   760	    {
   761	      return -EIO;
   762	    }
   763	
   764	  /* The L2H_MAILBOX (0x40002000) is on the LPSYS APB bus.  Its CxIER
   765	   * register is only writable when the LPSYS bus bridge is active.
   766	   * Wake the LCPU first so the bus bridge is powered, THEN open the
   767	   * IPC queue (which writes CxIER to unmask the mailbox RX interrupt).
   768	   * The SDK reference ipc_hw_enable_interrupt2() has the same
   769	   * HAL_HPAON_WakeCore() before the UNMASK call.
   770	   */
   771	
   772	  HAL_HPAON_WakeCore(CORE_ID_LCPU);
   773	  g_sf32lb52_bt_env.wake_held = true;
   774	
   775	  usleep(500000);
   776	
   777	  ret = ipc_queue_open(g_sf32lb52_bt_env.ipc_port);
   778	  if (ret < 0)
   779	    {
   780	      HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
   781	      g_sf32lb52_bt_env.wake_held = false;
   782	      return ret;
   783	    }
   784	
   785	  /* Flush H2L TX ring to SRAM immediately after ipc_queue_open so
   786	   * LCPU sees the reset indices (read_idx=write_idx=0) before it
   787	   * tries to process any stale data from a previous session.
   788	   */
   789	  up_clean_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
   790	                  (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
   791	                  SF32LB52_BT_TX_BUF_SIZE);
   792	  __DSB();
   793	
   794	  /* After every lcpu_power_on(), LCPU resets its TX ring write pointer
   795	   * (write_idx_mirror) to 0 and writes its own boot responses into the
   796	   * ring.  HCPU's read pointer (read_idx_mirror) may still hold the
   797	   * non-zero value from the previous session -- dirty in DCache or
   798	   * stored in SRAM.  If we do not synchronise them:
   799	   *
   800	   *   circular_buf_data_len() = wrap(write_idx - read_idx)
   801	   *
   802	   * returns a large garbage value, and LCPU's fresh boot events
   803	   * plus ring garbage all replay as "new" HCI responses.  These
   804	   * ghost events are consumed by the host as replies to real commands,
   805	   * so HCI_Reset (0x0c01) is never actually executed by the controller,
   806	   * and bt_le_adv_start later gets "Command Disallowed" (0x07).
   807	   *
   808	   * Fix: flush DCache to write back any dirty read_idx and to load
   809	   * LCPU's current write_idx from SRAM, then advance read_idx to
   810	   * write_idx (discard ALL pending LCPU boot data), then clean the
   811	   * DCache so LCPU sees the updated read pointer in SRAM.
   812	   */
   813	
   814	  {
   815	    struct circular_buf *rx_ring =
   816	        (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
   817	
   818	    ret = sf32lb52_bt_wait_rx_ring_ready();
   819	    if (ret < 0)
   820	      {
   821	        syslog(LOG_ERR, "sf32lb52 rx ring not ready: %d\n", ret);
   822	        ipc_queue_close(g_sf32lb52_bt_env.ipc_port);
   823	        HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
   824	        g_sf32lb52_bt_env.wake_held = false;
   825	        return ret;
   826	      }
   827	
   828	    rx_ring->read_idx_mirror = rx_ring->write_idx_mirror;
   829	    g_sf32lb52_bt_env.rx_read_idx_mirror = rx_ring->write_idx_mirror;
   830	
   831	    up_clean_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
   832	                    (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
   833	                    sizeof(*rx_ring));
   834	    __DSB();
   835	  }
   836	
   837	  {
   838	    volatile MAILBOX_CH_TypeDef *l2h = L2H_MAILBOX;
   839	    uint32_t nvic_bit = (1UL << (LCPU2HCPU_IRQn & 0x1F));
   840	    uint32_t nvic_en  = NVIC->ISER[LCPU2HCPU_IRQn >> 5];
   841	
   842	    (void)l2h;
   843	    (void)nvic_bit;
   844	    (void)nvic_en;
   845	  }
   846	
   847	  g_sf32lb52_bt_env.queue_open = true;
   848	  g_sf32lb52_bt_status = SF32LB52_BT_STATUS_ENABLED;
   849	
   850	  return OK;
   851	}
   852	
   853	int sf32lb52_bt_controller_disable(void)
   854	{
   855	  int ret = OK;
   856	  int tmpret;
   857	  bool queue_open;
   858	
   859	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_ENABLED)
   860	    {
   861	      return -EPERM;
   862	    }
   863	
   864	  queue_open = g_sf32lb52_bt_env.queue_open;
   865	  g_sf32lb52_bt_env.queue_open = false;
   866	  g_sf32lb52_bt_env.rx_work_pending = false;
   867	  g_sf32lb52_bt_env.rx_worker_running = false;
   868	  if (!work_available(&g_sf32lb52_bt_env.rx_work))
   869	    {
   870	      tmpret = work_cancel_sync(HPWORK, &g_sf32lb52_bt_env.rx_work);
   871	      if (tmpret < 0 && tmpret != -ENOENT && ret == OK)
   872	        {
   873	          ret = tmpret;
   874	        }
   875	    }
   876	
   877	  if (queue_open)
   878	    {
   879	      tmpret = ipc_queue_close(g_sf32lb52_bt_env.ipc_port);
   880	      if (tmpret < 0 && ret == OK)
   881	        {
   882	          ret = tmpret;
   883	        }
   884	    }
   885	
   886	  if (g_sf32lb52_bt_env.wake_held)
   887	    {
   888	      HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
   889	      g_sf32lb52_bt_env.wake_held = false;
   890	    }
   891	
   892	  tmpret = lcpu_power_off();
   893	  if (tmpret != 0 && ret == OK)
   894	    {
   895	      ret = -EIO;
   896	    }
   897	
   898	  g_sf32lb52_bt_env.notify_host = NULL;
   899	  g_sf32lb52_bt_status = SF32LB52_BT_STATUS_INITED;
   900	  return ret;
