   184	static uint32_t probe_get_le32(const uint8_t *value)
   185	{
   186	  return (uint32_t)value[0] |
   187	         ((uint32_t)value[1] << 8) |
   188	         ((uint32_t)value[2] << 16) |
   189	         ((uint32_t)value[3] << 24);
   190	}
   191	
   192	static void probe_put_le32(uint8_t *value, uint32_t number)
   193	{
   194	  value[0] = (uint8_t)number;
   195	  value[1] = (uint8_t)(number >> 8);
   196	  value[2] = (uint8_t)(number >> 16);
   197	  value[3] = (uint8_t)(number >> 24);
   198	}
