   200	static bt_status_t probe_notify(gatts_handle_t srv_handle,
   201	                                uint8_t *value, uint16_t length)
   202	{
   203	  bt_address_t peer_addr;
   204	  bool ready;
   205	
   206	  pthread_mutex_lock(&g_state_lock);
   207	  ready = g_peer_connected && g_notify_enabled;
   208	  memcpy(&peer_addr, &g_peer_addr, sizeof(peer_addr));
   209	  pthread_mutex_unlock(&g_state_lock);
   210	
   211	  if (!ready)
   212	    {
   213	      printf("openvela_ble_probe: TX notification not subscribed\n");
   214	      return BT_STATUS_NOT_READY;
   215	    }
   216	
   217	  return bt_gatts_notify(srv_handle, &peer_addr, PROBE_TX_HANDLE,
   218	                         value, length);
   219	}
