   297	static void probe_process_frame(gatts_handle_t srv_handle,
   298	                                const uint8_t *value, uint16_t length)
   299	{
   300	  uint8_t response[21];
   301	  uint8_t *reply;
   302	  uint16_t reply_len;
   303	  uint32_t elapsed_ms;
   304	  uint32_t id_or_seq;
   305	  uint32_t seq;
   306	  bt_status_t status;
   307	
   308	  if (length == 4 && memcmp(value, "PING", 4) == 0)
   309	    {
   310	      reply = g_pong;
   311	      reply_len = sizeof(g_pong);
   312	      printf("openvela_ble_probe: RX PING\n");
   313	    }
   314	  else if (length >= 1 && value[0] == 0x01)
   315	    {
   316	      if (length < 5)
   317	        {
   318	          printf("openvela_ble_probe: short binary PING length=%u\n",
   319	                 length);
   320	          return;
   321	        }
   322	
   323	      id_or_seq = probe_get_le32(&value[1]);
   324	      response[0] = 0x81;
   325	      probe_put_le32(&response[1], id_or_seq);
   326	      printf("openvela_ble_probe: RX binary PING seq=%lu\n",
   327	             (unsigned long)id_or_seq);
   328	      status = probe_notify(srv_handle, response, 5);
   329	      printf("openvela_ble_probe: TX binary PONG status=%d\n", status);
   330	      return;
   331	    }
   332	  else if (length >= 1 && value[0] == 0x10)
   333	    {
   334	      if (length < 5)
   335	        {
   336	          printf("openvela_ble_probe: short START length=%u\n", length);
   337	          return;
   338	        }
   339	
   340	      id_or_seq = probe_get_le32(&value[1]);
   341	      memset(&g_throughput, 0, sizeof(g_throughput));
   342	      g_throughput.active = true;
   343	      g_throughput.test_id = id_or_seq;
   344	
   345	      response[0] = 0x90;
   346	      probe_put_le32(&response[1], id_or_seq);
   347	      printf("openvela_ble_probe: throughput START test_id=%lu\n",
   348	             (unsigned long)id_or_seq);
   349	      status = probe_notify(srv_handle, response, 5);
   350	      printf("openvela_ble_probe: throughput START_ACK status=%d\n", status);
   440	      memset(&g_throughput, 0, sizeof(g_throughput));
   441	      return;
   442	    }
   443	  else
   444	    {
   445	      reply = g_error;
   446	      reply_len = sizeof(g_error);
   447	      printf("openvela_ble_probe: RX unknown command\n");
   448	    }
   449	
   450	  status = probe_notify(srv_handle, reply, reply_len);
   451	  printf("openvela_ble_probe: TX notify status=%d\n", status);
   452	}
