   221	static uint32_t probe_elapsed_ms(const struct timespec *started_at)
   222	{
   223	  struct timespec ended_at;
   224	  int64_t seconds;
   225	  int64_t nanoseconds;
   226	  uint64_t milliseconds;
   227	
   228	  if (clock_gettime(CLOCK_MONOTONIC, &ended_at) < 0)
   229	    {
   230	      return 0;
   231	    }
   232	
   233	  seconds = ended_at.tv_sec - started_at->tv_sec;
   234	  nanoseconds = ended_at.tv_nsec - started_at->tv_nsec;
   235	  if (nanoseconds < 0)
   236	    {
   237	      seconds--;
   238	      nanoseconds += 1000000000;
   239	    }
   240	
   241	  if (seconds < 0)
   242	    {
   243	      return 0;
   244	    }
   245	
   246	  milliseconds = (uint64_t)seconds * 1000 +
   247	                 (uint64_t)nanoseconds / 1000000;
   248	  return milliseconds > UINT32_MAX ? UINT32_MAX : (uint32_t)milliseconds;
   249	}
