   256	                                         __ATOMIC_RELAXED),
   257	         (unsigned long)__atomic_load_n(&g_rx_drop_lock_busy,
   258	                                         __ATOMIC_RELAXED),
   259	         (unsigned long)__atomic_load_n(&g_rx_drop_full,
   260	                                         __ATOMIC_RELAXED),
   261	         (unsigned long)__atomic_load_n(&g_rx_high_water,
