   267	static uint16_t probe_tx_cccd_written(gatts_handle_t srv_handle,
   268	                                      bt_address_t *addr,
   269	                                      uint16_t attr_handle,
   270	                                      const uint8_t *value,
   271	                                      uint16_t length,
   272	                                      uint16_t offset)
   273	{
   274	  bool notify_enabled;
   275	  uint16_t cccd;
   276	
   277	  (void)srv_handle;
   278	  (void)attr_handle;
   279	
   280	  if (offset != 0 || length < 2)
   281	    {
   282	      printf("openvela_ble_probe: invalid CCCD write\n");
   283	      return 0;
   284	    }
   285	
   286	  cccd = (uint16_t)value[0] | ((uint16_t)value[1] << 8);
   287	  pthread_mutex_lock(&g_state_lock);
   288	  memcpy(&g_peer_addr, addr, sizeof(g_peer_addr));
   289	  g_notify_enabled = (cccd & GATT_CCC_NOTIFY) != 0;
   290	  notify_enabled = g_notify_enabled;
   291	  pthread_mutex_unlock(&g_state_lock);
   292	
   293	  printf("openvela_ble_probe: TX notify=%d\n", notify_enabled);
   294	  return length;
   295	}
