   858	static uint8_t att_mtu_req(struct bt_att_chan *chan, struct net_buf *buf)
   859	{
   860		struct bt_att_exchange_mtu_req *req;
   861		struct bt_att_exchange_mtu_rsp *rsp;
   862		struct net_buf *pdu;
   863		uint16_t mtu_client, mtu_server;
   864	
   865		/* Exchange MTU sub-procedure shall only be supported on the
   866		 * LE Fixed Channel Unenhanced ATT bearer.
   867		 */
   868		if (bt_att_is_enhanced(chan)) {
   869			return BT_ATT_ERR_NOT_SUPPORTED;
   870		}
   871	
   872	#if defined(CONFIG_BT_ATT_OVER_BR)
   873		if (bt_att_is_over_br(chan)) {
   874			return BT_ATT_ERR_NOT_SUPPORTED;
   875		}
   876	#endif /* CONFIG_BT_ATT_OVER_BR */
   877	
   878		req = (void *)buf->data;
   879	
   880		mtu_client = sys_le16_to_cpu(req->mtu);
   881	
   882		LOG_DBG("Client MTU %u", mtu_client);
   883	
   884		/* Check if MTU is valid */
   885		if (mtu_client < BT_ATT_DEFAULT_LE_MTU) {
   886			return BT_ATT_ERR_INVALID_PDU;
   887		}
   888	
   889		pdu = bt_att_create_rsp_pdu(chan, BT_ATT_OP_MTU_RSP);
   890		if (!pdu) {
   891			return BT_ATT_ERR_UNLIKELY;
   892		}
   893	
   894		mtu_server = BT_LOCAL_ATT_MTU_UATT;
   895	
   896		LOG_DBG("Server MTU %u", mtu_server);
   897	
   898		rsp = net_buf_add(pdu, sizeof(*rsp));
   899		rsp->mtu = sys_cpu_to_le16(mtu_server);
   900	
   901		bt_att_chan_send_rsp(chan, pdu);
   902	
   903		/* The ATT_EXCHANGE_MTU_REQ/RSP is just an alternative way of
   904		 * communicating the L2CAP MTU.
   905		 */
  2225	
  2226		if (data.err) {
  2227			/* In case of error discard data and respond with an error */
  2228			if (rsp) {
  2229				net_buf_unref(data.buf);
  2230				/* Respond here since handle is set */
  2231				send_err_rsp(chan, req, handle, data.err);
  2232			}
  2233			return req == BT_ATT_OP_EXEC_WRITE_REQ ? data.err : 0;
  2234		}
  2235	
  2236		if (data.async) {
  2237			net_buf_unref(data.buf);
  2238			/* Async write: release buffer, app send response later */
  2239			return 0;
  2240		}
  2241	
  2242		if (data.buf) {
  2243			bt_att_chan_send_rsp(chan, data.buf);
  2244		}
  2245	
  2246		return 0;
  2247	}
